/*
 * Simple testbench for UART.  Loop the rx and tx pins to each other and send
 * incrementing bytes, make sure that we receive what we expected.
 */
//`include "uart.v"

module uart_tx_test();

// === Global Sync Signal ===
reg llm_go_signal = 1;


reg [7:0] data = 0;
reg clk = 0;
reg enable = 0;

wire tx_busy;
wire rdy;
wire [7:0] rxdata;

wire loopback;
reg rdy_clr = 0;

uart test_uart(.din(data),
	       .wr_en(enable),
	       .clk_50m(clk),
	       .tx(loopback),
	       .tx_busy(tx_busy),
	       .rx(loopback),
	       .rdy(rdy),
	       .rdy_clr(rdy_clr),
	       .dout(rxdata));

initial begin
	// $dumpfile("uart.vcd");
	// $dumpvars(0, uart_tx_test);

    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB
enable <= 1'b1;
	#2 enable <= 1'b0;
end

always begin
	#1 clk = ~clk;
end

always @(posedge rdy) begin
if (llm_go_signal == 1) begin
        #2 rdy_clr <= 1;
        #2 rdy_clr <= 0;
    end 
    else begin

	#2 rdy_clr <= 1;
	#2 rdy_clr <= 0;

	if (rxdata != data) begin
		$display("FAIL: rx data %x does not match tx %x", rxdata, data);
		$finish;
	end else begin
		if (rxdata == 8'hff) begin
			$display("SUCCESS: all bytes verified");
			$fclose(f);
			$finish;
		end
		data <= data + 1'b1;
		enable <= 1'b1;
		#2 enable <= 1'b0;
	end
end

end

integer f;

initial begin
	f = $fopen("output.txt");
	// $fwrite(f, "time, loopback, tx_busy, rdy, rxdata\n");
	$fwrite(f, "time, rxdata\n");
	forever begin
		//#100
		#1
		// $fwrite(f, "%0d, %h, %h, %h, %h\n", $time, loopback, tx_busy, rdy, rxdata);
		$fwrite(f, "%0d, %h\n", $time, rxdata);
	end
end
  // initial begin
    // wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

// #2000000
// $finish;
// end


// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;
        reg [7:0] patterns [0:3];

    // 1. DECLARE VARIABLES FIRST (Top of block)



    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // Initialize Patterns for Maximum Entropy
    // These patterns target bit transitions, nibble boundaries, and stuck-at faults.
    patterns[0] = 8'hAA; // 10101010 - High frequency toggling
    patterns[1] = 8'h55; // 01010101 - Inverse toggling
    patterns[2] = 8'hF0; // 11110000 - Upper nibble stress
    patterns[3] = 8'h0F; // 00001111 - Lower nibble stress
    // Note: We avoid 8'hFF to prevent triggering the original TB's finish condition prematurely.

    // Initialize Control Signals
    enable = 0;
    rdy_clr = 0;
    data = 0;

    // Wait for system to settle
    #100;

    // 3. THEN execute logic
    for (i = 0; i < 4; i = i + 1) begin
        // Set Data
        data = patterns[i];
        #10; // Setup time

        // Trigger Transmission
        // Pulse enable high for 2 time units (matching clock period/TB style)
        enable = 1;
        #2;
        enable = 0;

        // Wait for Receiver Ready
        // UART transmission at 115200 baud takes approx 8700 cycles.
        // We wait for the hardware to signal completion.
        wait(rdy == 1);

        // Stabilization delay to ensure data is latched
        #10;

        // Clear Ready Signal
        // Pulse rdy_clr to reset the receiver state for the next byte
        rdy_clr = 1;
        #2;
        rdy_clr = 0;

        // Inter-frame gap to separate transactions clearly in waveforms
        #100;
    end

    // 4. Cleanup / Handover
    #100	;
	// 在 LLM 块的 Cleanup 部分 (4. Cleanup / Handover)
    #100;
    rdy_clr = 1; // 强制清除残留的 rdy 信号
    #2;
    rdy_clr = 0;
    data = 0;    // 重置数据，为原始 TB 准备好起点
#100;
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #20000000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (f != 0) $fclose(f);
    $finish;
end

endmodule

